//! Lucene's precomputed parametric Levenshtein transition tables.
//!
//! Transcribed mechanically from Lucene 10.5.0's `Lev1ParametricDescription`,
//! `Lev1TParametricDescription`, `Lev2ParametricDescription` and
//! `Lev2TParametricDescription` (themselves generated by
//! `gradle/generation/moman/createAutomata.py`). Each description is a list of
//! levels, one per `position == w - k` branch of the Java `transition` method
//! (the last level is its `else` branch), and each level carries the
//! `(state limit, offsetIncrs bits, offsetIncrs, toStates bits, toStates)` of
//! that branch. The packed words are Java `long`s; they are only ever shifted
//! and then masked to the unpacked width, so reading them as `u64` is exact.

/// One `position == w - k` branch of a parametric description.
pub(super) struct Level {
    pub(super) state_limit: i32,
    pub(super) offset_bits: u32,
    pub(super) offset_incrs: &'static [u64],
    pub(super) to_bits: u32,
    pub(super) to_states: &'static [u64],
}

/// A whole parametric description: its levels, `n` and `minErrors`.
pub(super) struct Description {
    pub(super) n: i32,
    pub(super) levels: &'static [Level],
    pub(super) min_errors: &'static [i32],
}

