const LEV1_OFFSETINCRS3: &[u64] = &[0x555555e80a0f0000, 0x5555];

const LEV1_LEVELS: &[Level] = &[
    Level {
        state_limit: 2,
        offset_bits: 1,
        offset_incrs: LEV1_OFFSETINCRS0,
        to_bits: 2,
        to_states: LEV1_TOSTATES0,
    },
    Level {
        state_limit: 3,
        offset_bits: 1,
        offset_incrs: LEV1_OFFSETINCRS1,
        to_bits: 2,
        to_states: LEV1_TOSTATES1,
    },
    Level {
        state_limit: 5,
        offset_bits: 2,
        offset_incrs: LEV1_OFFSETINCRS2,
        to_bits: 3,
        to_states: LEV1_TOSTATES2,
    },
    Level {
        state_limit: 5,
        offset_bits: 2,
        offset_incrs: LEV1_OFFSETINCRS3,
        to_bits: 3,
        to_states: LEV1_TOSTATES3,
    },
];

/// `Lev1ParametricDescription`.
pub(super) static LEV1: Description = Description {
    n: 1,
    levels: LEV1_LEVELS,
    min_errors: &[0, 1, 0, -1, -1],
};

